function forms(string $s):array{$raw=trim($s);if($raw==='')return[];$variants=[$raw];$x=preg_replace('/\s*\((?:ex|ех)\.?[^)]*\)\s*$/iu','',$raw);if(is_string($x)&&trim($x)!==''&&trim($x)!==$raw)$variants[]=trim($x);$out=[];foreach($variants as$v){$n=norm($v);if($n==='')continue;$out[$n]=1;$t=preg_split('/\s+/u',$n,-1,PREG_SPLIT_NO_EMPTY)?:[];$g=array_values(array_filter($t,static fn($z)=>$z!=='hotel'&&$z!=='отель'));if($g&&count($g)!==count($t))$out[implode(' ',$g)]=1;}return array_keys($out);}
function prot($v,string $k='',int $d=0):bool{if($d>24)return true;if(is_array($v)){foreach($v as$kk=>$x)if(prot($x,(string)$kk,$d+1))return true;return false;}if(!preg_match('/manual|exclude|exclusion|conflict|reject|review|protect/i',$k))return false;if(is_bool($v))return$v;if(is_numeric($v))return(float)$v!=0.0;return is_string($v)&&!in_array(strtolower(trim($v)),['','false','none','no','null','0'],true);}
function bridge(array $e):?array{$b=$e['provider_bridges'][0]??null;if(!is_array($b))return null;$aid=trim((string)($b['andromeda_hotel_id']??''));$country=filter_var($b['country_id']??null,FILTER_VALIDATE_INT);$name=trim((string)($b['hotel_name']??''));if($aid===''||!ctype_digit($aid)||$country===false||(int)$country<=0||$name==='')return null;$lat=null;$lon=null;foreach(['latitude','lat']as$k)if(isset($b[$k])&&is_numeric($b[$k])){$lat=(float)$b[$k];break;}foreach(['longitude','lon','lng']as$k)if(isset($b[$k])&&is_numeric($b[$k])){$lon=(float)$b[$k];break;}return['andromeda_id'=>$aid,'country_id'=>(int)$country,'hotel_name'=>$name,'latitude'=>$lat,'longitude'=>$lon];}
function km(float $a,float $b,float $c,float $d):float{$r=6371.0;$p1=deg2rad($a);$p2=deg2rad($c);$dp=deg2rad($c-$a);$dl=deg2rad($d-$b);$x=sin($dp/2)**2+cos($p1)*cos($p2)*sin($dl/2)**2;return 2*$r*asin(min(1.0,sqrt($x)));}
function writej(string $p,array $v):string{$j=json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)."\n";$f=@fopen($p,'x+b');req(is_resource($f),'exclusive_output');try{req(fwrite($f,$j)===strlen($j)&&fflush($f),'write');if(function_exists('fsync'))req(fsync($f),'sync');rewind($f);req(stream_get_contents($f)===$j,'readback');}finally{fclose($f);}return hash('sha256',$j);}
